import { Page, Locator, expect } from '@playwright/test';

/**
 * Page Object Model representing the MainView (Homepage / Landing Page).
 * Kapselt alle Buttons, Header, Footer und Navigations-Elemente der Startseite
 * unter Verwendung der ScalaJS HTML-IDs (#MainView_BtnOption1, #MainView_BtnSearch etc.).
 */
export class MainViewPage {
  readonly page: Page;

  // Key Action Buttons on Home Page (HTML-IDs generated by ScalaJS)
  readonly btnOption1: Locator;
  readonly btnOption2: Locator;
  readonly btnSearch: Locator;

  // Header & Navigation Elements
  readonly brandLogo: Locator;
  readonly navLoginBtn: Locator;
  readonly navManagementBtn: Locator;

  // Footer Links for Static Pages
  readonly footerPrivacyLink: Locator;
  readonly footerImpressumLink: Locator;
  readonly footerContactLink: Locator;
  readonly footerGtcLink: Locator;
  readonly footerPricingLink: Locator;

  // Static Content Area
  readonly staticPageTitle: Locator;
  readonly staticPageContent: Locator;

  // DlgStartDemo Dialog Locators
  readonly btnDemo: Locator;
  readonly dlgStartDemoModal: Locator;
  readonly dlgStartDemoTitle: Locator;
  readonly dlgStartDemoPrompt: Locator;
  readonly btnStartDemoApply: Locator;
  readonly btnStartDemoCancel: Locator;

  // DlgStartTourney Dialog Locators
  readonly dlgStartTourneyModal: Locator;
  readonly dlgStartTourneyTitle: Locator;
  readonly dlgStartTourneyPrompt: Locator;
  readonly btnStartTourneyApply: Locator;
  readonly btnStartTourneyCancel: Locator;

  // DlgStartCompetition Dialog Locators
  readonly dlgStartCompetitionModal: Locator;
  readonly dlgStartCompetitionTitle: Locator;
  readonly dlgStartCompetitionPrompt: Locator;
  readonly btnStartCompetitionApply: Locator;
  readonly btnStartCompetitionCancel: Locator;

  // Key Action Buttons on Home Page (HTML-IDs generated by ScalaJS)
  readonly btnDemoBox: Locator;
  readonly btnOption1: Locator;
  readonly btnOption2: Locator;
  readonly btnSearch: Locator;
  readonly statusTourneyBar: Locator;
  readonly statusTourneyLabel: Locator;
  readonly statusTourneyIcon: Locator;
  readonly statusTourneyName: Locator;
  readonly btnStatusLoadLast: Locator;

  constructor(page: Page) {
    this.page = page;

    // Encapsulate exact HTML-IDs generated by MainView.scala
    this.btnDemoBox = page.locator('#MainView_BtnDemo');
    this.btnOption1 = page.locator('#MainView_BtnOption1');
    this.btnOption2 = page.locator('#MainView_BtnOption2');
    this.btnSearch = page.locator('#MainView_BtnSearch');
    this.statusTourneyBar = page.locator('#MainView_StatusTourney');
    this.statusTourneyLabel = page.locator('#MainView_StatusTourney span.fw-semibold');
    this.statusTourneyIcon = page.locator('#MainView_StatusTourney .container i.bi').first();
    this.statusTourneyName = page.locator('#MainView_StatusTourneyName');
    this.btnStatusLoadLast = page.locator('#MainView_BtnLoadLast');

    // Header & Navigation
    this.brandLogo = page.locator('.navbar-brand');
    this.navLoginBtn = page.locator('#navbar-login, .navbar .btn:has-text("Anmelden"), .navbar .btn:has-text("Login")');
    this.navManagementBtn = page.locator('#navbarManagement, .navbar a:has-text("Management"), .navbar .btn:has-text("Management")');
    this.btnDemo = page.locator('#MainView_BtnDemo');

    // DlgStartDemo Dialog
    this.dlgStartDemoModal = page.locator('div[id*="DlgStartDemo_ModalId"].modal');
    this.dlgStartDemoTitle = page.locator('h5[id*="DlgStartDemo_TitleId"]');
    this.dlgStartDemoPrompt = page.locator('p[id*="DlgStartDemo_PromptId"], div[id*="DlgStartDemo_ModalId"] .modal-body p');
    this.btnStartDemoApply = page.locator('button[id*="DlgStartDemo_ApplyId"]');
    this.btnStartDemoCancel = page.locator('button[id*="DlgStartDemo_CancelId"]');

    // DlgStartTourney Dialog
    this.dlgStartTourneyModal = page.locator('div[id*="DlgStartTourney_ModalId"].modal');
    this.dlgStartTourneyTitle = page.locator('h5[id*="DlgStartTourney_TitleId"]');
    this.dlgStartTourneyPrompt = page.locator('p[id*="DlgStartTourney_PromptId"], div[id*="DlgStartTourney_ModalId"] .modal-body p');
    this.btnStartTourneyApply = page.locator('button[id*="DlgStartTourney_ApplyId"]');
    this.btnStartTourneyCancel = page.locator('button[id*="DlgStartTourney_CancelId"]');

    // DlgStartCompetition Dialog
    this.dlgStartCompetitionModal = page.locator('div[id*="DlgStartCompetition_ModalId"].modal');
    this.dlgStartCompetitionTitle = page.locator('h5[id*="DlgStartCompetition_TitleId"]');
    this.dlgStartCompetitionPrompt = page.locator('p[id*="DlgStartCompetition_PromptId"], div[id*="DlgStartCompetition_ModalId"] .modal-body p');
    this.btnStartCompetitionApply = page.locator('button[id*="DlgStartCompetition_ApplyId"]');
    this.btnStartCompetitionCancel = page.locator('button[id*="DlgStartCompetition_CancelId"]');

    // Footer Links (using appLoadPage calls or href)
    this.footerPrivacyLink = page.locator('a[href*="privacy"], a[href*="dataprotection"]');
    this.footerImpressumLink = page.locator('a[href*="impressum"], a[href*="imprint"]');
    this.footerContactLink = page.locator('a[href*="contact"], a[href*="kontakt"]');
    this.footerGtcLink = page.locator('a[href*="gtc"], a[href*="agb"]');
    this.footerPricingLink = page.locator('a[href*="pricing"], a[href*="preise"]');

    // Content container for static pages
    this.staticPageTitle = page.locator('h1, h2.dp-title, .page-header-title');
    this.staticPageContent = page.locator('#content, .dp-container');
  }

  /**
   * Navigates directly to the MainView home URL.
   */
  async goto() {
    await this.page.goto('/');
    await this.page.waitForLoadState('domcontentloaded');
  }

  /**
   * Clicks the MainSearch button to open the search page.
   */
  async clickSearch() {
    await this.btnSearch.click();
    await expect(this.page.locator('#MainSearch_IdInputTitle')).toBeVisible();
  }

  /**
   * Clicks Option 1 (New Tournament) and optionally confirms the DlgStartTourney modal.
   */
  async clickOption1(confirm: boolean = false) {
    await this.btnOption1.click();
    if (confirm) {
      await this.btnStartTourneyApply.waitFor({ state: 'visible', timeout: 5000 });
      await this.btnStartTourneyApply.click();
      await expect(this.dlgStartTourneyModal).not.toBeVisible({ timeout: 7000 });
    }
  }

  /**
   * Starts a full tournament by clicking Option 1 and confirming the DlgStartTourney modal.
   */
  async startFullTourney() {
    await this.clickOption1(true);
  }

  /**
   * Clicks Option 2 (Quick Start Competition) and optionally confirms the DlgStartCompetition modal.
   */
  async clickOption2(confirm: boolean = false) {
    await this.btnOption2.click();
    if (confirm) {
      await this.btnStartCompetitionApply.waitFor({ state: 'visible', timeout: 5000 });
      await this.btnStartCompetitionApply.click();
      await expect(this.dlgStartCompetitionModal).not.toBeVisible({ timeout: 7000 });
    }
  }

  /**
   * Starts a quick competition by clicking Option 2 and confirming the DlgStartCompetition modal.
   */
  async startQuickCompetition() {
    await this.clickOption2(true);
  }

  /**
   * Clicks the Demo button in the MainView container.
   */
  async clickDemoBox() {
    await this.btnDemoBox.click();
  }

  /**
   * Asserts that essential homepage elements are visible.
   */
  async assertPageLoaded() {
    await expect(this.btnDemoBox).toBeVisible();
    await expect(this.btnOption1).toBeVisible();
    await expect(this.btnOption2).toBeVisible();
    await expect(this.btnSearch).toBeVisible();
  }

  /**
   * Starts a demo tournament by clicking the Demo button and confirming the DlgStartDemo modal if present.
   */
  async startDemo() {
    await this.btnDemo.first().click();
    if (await this.dlgStartDemoModal.isVisible({ timeout: 1500 }).catch(() => false)) {
      await this.btnStartDemoApply.click();
      await expect(this.dlgStartDemoModal).not.toBeVisible({ timeout: 7000 });
    }
  }
}
